poses.push(...[{"ko": ["0.5× 항공샷", "카메라는 높게, 시선은 위로.", "휴대폰을 머리 위로 들고 렌즈가 아래를 향하도록 기울여요.", "턱을 살짝 들고 렌즈를 바라봐요. 발끝까지 담아 옷과 배경을 함께 보여주세요.", "휴대폰 기본 카메라에서 지원된다면 0.5×를 사용해요. 이 웹앱은 초광각 렌즈 전환을 지원하지 않아요."], "ja": ["0.5× ハイアングル", "カメラを高く、視線は上へ。", "スマホを頭より高く持ち、レンズを下に向けます。", "少し顔を上げてレンズを見て。足先まで入れると、服と背景も一緒に写せます。", "標準カメラが対応していれば0.5×を試して。このWebアプリでは超広角レンズへの切替はできません。"], "tag": "항공샷", "bg": "#f2e5d9", "kind": "HIGH ANGLE", "source": "https://www.newsis.com/view/NISX20240517_0002738118", "sourceLabel": "NEWSIS · 2024.05.17", "cameraTip": ["머리 위에서 아래로 촬영하세요. 0.5×는 휴대폰 기본 카메라에서 선택할 수 있어요.", "頭の上から下に向けて撮影。0.5×はスマホの標準カメラで選べます。"]}, {"ko": ["무심한 거울 셀카", "오늘의 룩을 프레임 가득.", "전신거울 앞에서 몸을 살짝 틀고, 한쪽 발을 반걸음 내밀어요.", "휴대폰으로 얼굴 일부를 가리고, 비어 있는 손은 가볍게 내려요.", "신발까지 프레임에 담아보세요. 화면 속 화면을 담고 싶다면 휴대폰의 셀카 화면을 거울 쪽으로 돌려보세요."], "ja": ["さりげない鏡セルフィー", "今日のコーデを、フレームいっぱいに。", "全身鏡の前で少し体を斜めにし、片足を半歩前へ。", "スマホで顔の一部を隠し、空いた手は自然に下ろします。", "靴までフレームに入れて。画面の中の画面を撮るなら、自撮り画面を鏡に向けてみましょう。"], "tag": "거울셀카", "bg": "#e8e8f1", "kind": "MIRROR SELFIE", "source": "https://ohou.se/advices/9483", "sourceLabel": "오늘의집 · 2023.07.27", "cameraTip": ["실제 거울을 향해 카메라를 들어주세요. 머리 위와 발끝에 여백을 남겨요.", "実際の鏡にカメラを向けて。頭の上と足元に余白を残しましょう。"]}, {"ko": ["고양이 그림자", "그림자도 귀여울 수 있잖아.", "햇빛이나 조명 아래에서 바닥에 그림자가 또렷하게 생기는 자리를 찾아요.", "팔을 몸 앞쪽으로 접어 팔꿈치로 귀를 만들고, 양손 손가락 세 개씩 펼쳐 수염을 만들어요.", "친구가 바닥의 그림자를 위에서 촬영해요. 화면을 보면서 귀와 수염이 겹치지 않게 조금씩 조절해요."], "ja": ["ねこの影ポーズ", "影だって、かわいくなれる。", "日差しや照明で、地面に影がくっきりできる場所を探します。", "腕を体の前で折り曲げ、ひじで耳を。両手の指を3本ずつ広げてヒゲにします。", "友だちに地面の影を上から撮ってもらいましょう。画面を見ながら耳とヒゲが重ならないよう調整して。"], "tag": "고양이그림자", "bg": "#e6e9dc", "kind": "SHADOW PLAY", "source": "https://sports.khan.co.kr/article/202505181240003", "sourceLabel": "스포츠경향 · 2025.05.18", "cameraTip": ["사람 대신 바닥의 그림자를 맞춰주세요. 밝은 곳에서 귀와 수염 윤곽을 확인해요.", "人物ではなく、地面の影を合わせて。明るい場所で耳とヒゲの輪郭を確認しましょう。"]}]);
