function renderSpots(){
 const preferred=['gyeongbok','hyundai','seongsu','jumunjin','bukchon','mangwon','mongted','hyeopjae'];
 const order=filter==='all'?[...preferred.map(id=>spots.find(s=>s.id===id)),...spots.filter(s=>!preferred.includes(s.id))]:spots;
 const matches=order.filter(s=>spotMatchesType(s,filter)&&[...s.ko,...(s.en||[]),...s.ja,s.map].join(' ').toLowerCase().includes(query.toLowerCase()));
 const shown=matches.slice(0,spotLimit);
 $('#spotGrid').innerHTML=shown.map(s=>{const a=s[lang]||s.ko;return `<article class="spot-card"><div class="card-image"><button class="card-photo-button" data-spot="${s.id}" aria-label="${a[0]} ${t('more')}"><img src="assets/${s.image}" alt="${a[0]} ${t('reference')}" loading="lazy"></button><span class="card-badge ${s.type}">${s.type==='local'?'K-PICK · ':s.type==='drama'?'▸ ':''}${a[2]}</span><button class="round-button save-button" data-save="${s.id}" aria-label="${a[0]} ${t('save')}">${icon('bookmark')}</button></div><div class="card-info"><div class="card-location">${icon('pin')}${a[1]}</div><button class="card-title" data-spot="${s.id}">${a[0]}</button><div class="card-tags"><span>${a[3]}</span><span>${a[4]}</span></div><div class="card-footer"><span class="ar-ready">${icon('scan')}${t('arReady')}</span><a href="${instagramSpotUrl(s)}" target="_blank" rel="noopener noreferrer" class="instagram-link" aria-label="${a[0]} ${t('instagramSpot')}">${t('instagramSpot')} ↗</a></div></div></article>`}).join('');
 $('#emptySearch').classList.toggle('hidden',matches.length>0);
 $('#catalogCount').textContent=matches.length+' '+t('spotCount')+' · '+shown.length+' '+t('visibleCount');
 $('#loadMoreSpots').classList.toggle('hidden',shown.length>=matches.length);$('#loadMoreSpots').innerHTML=t('moreSpots')+' <span>'+shown.length+' / '+matches.length+'</span> ↓';
 $('#localIntro').classList.toggle('hidden',filter!=='local');
 document.querySelectorAll('[data-filter]').forEach(b=>{let count=b.querySelector('.filter-count');if(!count){count=document.createElement('span');count.className='filter-count';b.append(count)}count.textContent=spots.filter(s=>spotMatchesType(s,b.dataset.filter)).length;b.setAttribute('aria-pressed',b.dataset.filter===filter)});
 updateSaved();
}
function updateSaved(){$('#saveCount').textContent=saved.length+(savedStyle?1:0);document.querySelectorAll('[data-save]').forEach(b=>{const active=saved.includes(b.dataset.save);b.classList.toggle('is-saved',active);b.setAttribute('aria-pressed',active);b.title=t(active?'saved':'save')})}
function toggleSave(id){if(saved.includes(id)){saved=saved.filter(s=>s!==id);toast(t('removed'))}else{saved.push(id);toast(t('added'))}persist('sf-saved',saved);updateSaved();}
function toneButtons(){const idx=lang==='ko'?0:lang==='ja'?1:2;return seasons.map((s,i)=>`<button class="tone-button ${i===style.season?'selected':''}" data-season="${i}" aria-pressed="${i===style.season}"><i style="background:${s.colors[0]}"></i>${s.name[idx]||s.en}</button>`).join('')}
function renderPoses(){$('#poseGrid').innerHTML=poseOrder.map((i,order)=>{const p=poses[i],a=p[lang]||p.ko;return `<button class="pose-card" data-pose="${i}"><div class="pose-drawing" style="background:${p.bg}">${poseSvg(i)}</div><div class="pose-copy"><span class="pose-index">${p.kind||'FRAME CLASSICS'} · 0${order+1}</span><h3>${a[0]}</h3><p>${a[1]}</p><span class="pose-go">↗</span></div></button>`}).join('')}
function showModal(html,type){stopCamera();$('#modalContent').innerHTML=html;modal.dataset.type=type;const heading=$('#modalContent h2');if(heading){heading.id='modalTitle';modal.setAttribute('aria-labelledby','modalTitle')}hydrate(modal);if(!modal.open)modal.showModal();modal.scrollTop=0;document.body.style.overflow='hidden';updateSaved();}
function closeModal(){modal.close();}
modal.addEventListener('close',()=>{stopCamera();document.body.style.overflow='';});$('#closeModal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function showSpot(id){const s=spots.find(s=>s.id===id),a=s[lang]||s.ko;showModal(`<img class="modal-hero" src="assets/${s.image}" alt="${a[0]}"><div class="modal-inner"><span class="eyebrow">PILK SNS BEST-CUT · ${a[2]}</span><h2>${a[0]}</h2><p>${icon('pin')} ${a[1]} · ${a[3]} ${a[4]}</p><div class="tip-card"><h4>✦ ${t('tips')}</h4><p>${a[5]}</p></div><a class="source-link" href="${s.source}" target="_blank" rel="noopener noreferrer">${t('visitInfo')} ↗</a><div class="modal-actions"><a class="button outline" target="_blank" rel="noopener noreferrer" href="${instagramSpotUrl(s)}">${t('instagramSpot')} ↗</a><button class="button primary" data-camera-pose="${s.pose}">${icon('scan')}${t('cameraGuide')}</button><a class="button outline" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.map)}">${icon('map')}${t('openMap')}</a><button class="button outline" data-save="${s.id}">${icon('bookmark')}${t('save')}</button></div></div>`,'spot')}
function showSaved(){showModal(`<div class="modal-inner"><div class="eyebrow">MY PILK COLLECTION</div><h2>${t('savedTitle')}</h2><p>${t('savedDesc')}</p><div class="save-list">${saved.map(id=>{const s=spots.find(s=>s.id===id),a=s[lang]||s.ko;return `<div class="saved-row"><button data-spot="${id}"><img src="assets/${s.image}" alt="${a[0]}"></button><button data-spot="${id}" style="text-align:left"><b>${a[0]}</b><small>${a[1]}</small></button><button data-remove="${id}" class="round-button" aria-label="${a[0]} ${t('delete')}">${icon('trash')}</button></div>`}).join('')}${savedStyle?`<div class="saved-row"><div style="width:78px;height:80px;display:flex;justify-content:center">${hanbokSvg(garmentColors[savedStyle.bottom].hex,savedStyle.design,false,savedStyle)}</div><button data-action="restoreStyle" style="text-align:left"><b>${t('styleSavedName')}</b><small>${seasons[savedStyle.season].en} · ${garmentColors[savedStyle.top][lang]||garmentColors[savedStyle.top].en}</small></button><button class="round-button" data-action="removeStyle" aria-label="${t('delete')}">${icon('trash')}</button></div>`:''}${!saved.length&&!savedStyle?`<div class="empty">${icon('bookmark')}<p>${t('noSaved')}</p><button class="button primary" data-action="discover">${t('findSpots')}</button></div>`:''}</div><p class="small-note">${t('localNote')}</p></div>`,'saved')}
function updateFaceCrop(){
 if(!portraitImage){faceData=null;return}
 const size=Math.min(portraitImage.width,portraitImage.height)/cropState.zoom;
 const sx=(portraitImage.width-size)*cropState.x/100,sy=(portraitImage.height-size)*cropState.y/100;
 const crop=document.createElement('canvas');crop.width=256;crop.height=256;
 crop.getContext('2d').drawImage(portraitImage,sx,sy,size,size,0,0,256,256);
 faceData=crop.toDataURL('image/png');
 const preview=$('#faceCropPreview');if(preview){const ctx=preview.getContext('2d');ctx.clearRect(0,0,160,160);ctx.drawImage(crop,0,0,160,160);ctx.strokeStyle='#fff8';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(80,80,57,70,0,0,Math.PI*2);ctx.stroke()}
}
async function loadPortrait(event){
 const file=event.target.files?.[0];if(!file)return;
 const error=$('#photoError'),input=event.target;error.textContent='';
 if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)){error.textContent=t('photoFormatError');input.value='';return}
 if(file.size>10*1024*1024){error.textContent=t('photoSizeError');input.value='';return}
 const token=++photoLoadId,url=URL.createObjectURL(file);
 try{const img=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=url});if(token!==photoLoadId)return;
 const resized=document.createElement('canvas'),scale=Math.min(1,1800/Math.max(img.naturalWidth,img.naturalHeight));resized.width=Math.max(1,Math.round(img.naturalWidth*scale));resized.height=Math.max(1,Math.round(img.naturalHeight*scale));resized.getContext('2d').drawImage(img,0,0,resized.width,resized.height);
 portraitImage=resized;Object.assign(cropState,{zoom:1.5,x:50,y:25});updateFaceCrop();
 if(modal.open&&modal.dataset.type==='style'){showStyle();toast(t('photoReady'))}
 }catch{if(token===photoLoadId&&$('#photoError'))$('#photoError').textContent=t('photoFormatError')}
 finally{URL.revokeObjectURL(url);input.value=''}
}
function removePortrait(){photoLoadId++;portraitImage=null;faceData=null;if(modal.open&&modal.dataset.type==='style')showStyle();}

function showQuiz(warm=null){showModal(`<div class="modal-inner"><span class="eyebrow">${t('quizEyebrow')}</span><h2>${t('quizTitle')}</h2><p>${t('quizDesc')}</p><h3>${warm===null?'01':'02'} / 02 &nbsp; ${t(warm===null?'quizQ1':'quizQ2')}</h3><div class="quiz-grid">${warm===null?`<button class="quiz-option" data-quiz="warm" style="background:#f7e9da"><span>☀</span>${t('quizWarm')}</button><button class="quiz-option" data-quiz="cool" style="background:#eeebf7"><span>☾</span>${t('quizCool')}</button>`:`<button class="quiz-option" data-quiz-result="${warm?0:3}" style="background:#f4edd9"><span>✦</span>${t('quizClear')}</button><button class="quiz-option" data-quiz-result="${warm?2:1}" style="background:#ece9e9"><span>✿</span>${t('quizSoft')}</button>`}</div></div>`,'quiz')}
function showPose(i){const p=poses[i],a=p[lang]||p.ko;showModal(`<div class="modal-inner"><span class="eyebrow">${p.kind||'FRAME CLASSICS'}</span><h2>${a[0]}</h2><p>${a[1]}</p><div class="pose-modal-drawing" style="background:${p.bg};border-radius:18px">${poseSvg(i)}</div><h4>${t('poseHow')}</h4><ol class="step-list">${a.slice(2).map(x=>`<li>${x}</li>`).join('')}</ol>${p.source?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${p.source}">${t('poseSource')} · ${p.sourceLabel} ↗</a>`:''}<div class="modal-actions"><button class="button primary" data-camera-pose="${i}">${icon('scan')}${t('poseCamera')}</button><a class="button outline" href="https://www.instagram.com/explore/tags/${encodeURIComponent(p.tag)}/" target="_blank" rel="noopener noreferrer">${t('instagram')} ↗</a></div></div>`,'pose')}
function stopCamera(){cameraToken++;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}if(window.speechSynthesis)window.speechSynthesis.cancel();}
function showCamera(pose=0){showModal(`<div class="camera-layout"><div class="camera-stage"><img src="assets/scene.jpg" alt="${t('gyeongbok')}"><video id="cameraVideo" autoplay playsinline muted></video><div class="camera-grid" id="cameraGrid"></div><div class="pose-overlay" id="poseOverlay">${poseSvg(pose,true)}</div><div class="camera-foot-line" id="cameraFootLine">▲ FOOT ALIGN LINE ▲</div><div class="camera-status" id="cameraStatus">${t('demo')}</div><div class="phone-flip-pill" id="phoneFlipBadge">🔄 ${pose===3?'0.5× HIGH ANGLE':'PHONE FLIP 180°'}</div><button class="camera-shutter" id="shutter" aria-label="${t('snap')}"></button></div><div class="camera-controls"><span class="eyebrow">PILK LIVE COACH</span><h2>${t('cameraTitle')}</h2><p>${t('cameraDesc')}</p><div class="camera-mode-tabs">${['A','B','C'].map(m=>`<button type="button" class="camera-mode-tab ${camMode===m?'selected':''}" data-cam-mode="${m}">Mode ${m}</button>`).join('')}</div><div class="camera-pose-tip" id="cameraPoseTip">${modeTips[camMode][lang]||modeTips[camMode].ko}</div><label for="cameraPose">${t('poseSelect')}</label><select id="cameraPose">${poses.map((p,i)=>`<option value="${i}" ${pose===i?'selected':''}>${(p[lang]||p.ko)[0]}</option>`).join('')}</select><label for="opacitySlider">${t('opacity')} <span id="opacityValue">65%</span></label><input id="opacitySlider" type="range" min="10" max="100" value="65"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="gridToggle" checked style="width:auto">${t('grid')}</label><button class="button primary" id="startCamera">${icon('camera')}${t('startCamera')}</button><p class="error" id="cameraError" role="status"></p><p class="small-note">${t('cameraNote')}</p></div></div>`,'camera');$('#cameraPose').onchange=e=>{const i=+e.target.value;$('#poseOverlay').innerHTML=poseSvg(i,true);$('#phoneFlipBadge').textContent=i===3?'📐 0.5× HIGH ANGLE':'🔄 PHONE FLIP 180°'};$('#opacitySlider').oninput=e=>{$('#poseOverlay').style.opacity=e.target.value/100;$('#opacityValue').textContent=e.target.value+'%'};$('#gridToggle').onchange=e=>{$('#cameraGrid').classList.toggle('hidden',!e.target.checked);$('#cameraFootLine').classList.toggle('hidden',!e.target.checked)};$('#startCamera').onclick=startCamera;$('#shutter').onclick=capturePhoto;}
async function startCamera(){if(stream){stopCamera();$('#cameraVideo').srcObject=null;$('#cameraVideo').style.display='none';$('#cameraStatus').textContent=t('demo');$('#startCamera').innerHTML=icon('camera')+t('startCamera');return}const token=++cameraToken;const button=$('#startCamera');button.disabled=true;$('#cameraError').textContent='';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Unavailable');const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1600},height:{ideal:1200}},audio:false});if(token!==cameraToken||!modal.open){media.getTracks().forEach(t=>t.stop());return}stream=media;const v=$('#cameraVideo');v.srcObject=stream;await v.play();v.style.display='block';$('#cameraStatus').textContent=t('live');button.innerHTML=icon('close')+t('stopCamera')}catch{if(token===cameraToken&&$('#cameraError'))$('#cameraError').textContent=t('cameraFail')}finally{button.disabled=false}}
function capturePhoto(){const v=$('#cameraVideo');if(!stream||!v||!v.videoWidth){toast(t('photoWait'));return}const canvas=document.createElement('canvas');canvas.width=v.videoWidth;canvas.height=v.videoHeight;const ctx=canvas.getContext('2d');ctx.drawImage(v,0,0);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`pilk-frame-${Date.now()}.jpg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('photoDone'))},'image/jpeg',.93)}
function showLocalCriteria(){showModal(`<div class="modal-inner"><span class="eyebrow">K-PICK / LOCAL EDIT</span><h2>${t('localTitle')}</h2><p>${t('localReason')}</p><ul class="credit-list"><li><a href="https://english.visitseoul.net/area/Yeonmujang-gil/ENP7u7jrk" target="_blank" rel="noopener noreferrer">Visit Seoul · 성수 연무장길</a></li><li><a href="https://mediahub.seoul.go.kr/archives/2014100" target="_blank" rel="noopener noreferrer">서울시 · 한남동</a></li><li><a href="https://culture.seoul.go.kr/culture/bbs/B0000001/view.do?menuNo=200051&nttId=13180" target="_blank" rel="noopener noreferrer">서울시 · 성수·한남 패션 거리</a></li></ul></div>`,'local')}
function showCredits(){showModal(`<div class="modal-inner"><span class="eyebrow">PHOTO CREDITS</span><h2>${t('creditsTitle')}</h2><p>${t('creditsDesc')}</p><ul class="credit-list"><li><a target="_blank" rel="noopener noreferrer" href="https://french.korea.net/NewsFocus/Society/view?articleId=136742">Korea.net · Gyeongbokgung Corridor</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.kh.or.kr/visit/en/bbsctt/list.do?key=2408080008">Korea Heritage Agency · Gyeongbokgung</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.kkday.com/ja/product/528728">KKday · Gyeongbokgung Hanbok</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://talesfromrails.com/posts/trips/2023-12-21-south-korea-by-train/">Tales from Rails · Bukchon Hanok Village</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://my.trip.com/moments/detail/gangneung-si-14776-145106173?locale=en-MY">Trip.com · Jumunjin Breakwater</a></li>${extraSpots.map(s=>`<li><a href="${s.source}" target="_blank" rel="noopener noreferrer">${(s[lang]||s.ko)[0]} · ${s.credit}</a></li>`).join('')}</ul></div>`,'credits')}
$('#ko').onclick=()=>setLanguage('ko');$('#en').onclick=()=>setLanguage('en');$('#ja').onclick=()=>setLanguage('ja');function setLanguage(l){if(modal.open)closeModal();lang=l;persist('sf-lang',l);render()}
$('#searchInput').oninput=e=>{query=e.target.value;spotLimit=8;renderSpots()};$('#viewAll').onclick=()=>{query='';filter='all';spotLimit=spots.length;$('#searchInput').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));renderSpots();$('#discover').scrollIntoView({behavior:'smooth'})};$('#openSaved').onclick=showSaved;$('#openStyling').onclick=showStyle;$('#openQuiz').onclick=()=>showQuiz();$('#credits').onclick=showCredits;$('#loadMoreSpots').onclick=()=>{spotLimit+=8;renderSpots()};$('#localCriteria').onclick=showLocalCriteria;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.camMode){camMode=b.dataset.camMode;document.querySelectorAll('[data-cam-mode]').forEach(x=>x.classList.toggle('selected',x===b));$('#cameraPoseTip').textContent=modeTips[camMode][lang]||modeTips[camMode].ko;if(camMode==='C'&&'speechSynthesis' in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(modeTips.C[lang]||modeTips.C.ko);u.lang=lang==='ko'?'ko-KR':lang==='ja'?'ja-JP':'en-US';window.speechSynthesis.speak(u)}return}if(b.dataset.save){toggleSave(b.dataset.save);return}if(b.dataset.spot){showSpot(b.dataset.spot);return}if(b.dataset.remove){saved=saved.filter(s=>s!==b.dataset.remove);persist('sf-saved',saved);showSaved();return}if(b.dataset.filter){filter=b.dataset.filter;spotLimit=8;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderSpots();return}if(b.dataset.season!==undefined){applySeason(+b.dataset.season);renderTone();updateStyle();return}if(b.dataset.color!==undefined){style.color=+b.dataset.color;renderTone();updateStyle();return}if(b.dataset.pose!==undefined){showPose(+b.dataset.pose);return}if(b.dataset.cameraPose!==undefined){showCamera(+b.dataset.cameraPose);return}if(b.dataset.quiz){showQuiz(b.dataset.quiz==='warm');return}if(b.dataset.quizResult!==undefined){applySeason(+b.dataset.quizResult);renderTone();showStyle();toast(t('quizResult'));return}switch(b.dataset.action){case'camera':showCamera();break;case'saved':showSaved();break;case'discover':closeModal();$('#discover').scrollIntoView({behavior:'smooth'});break;case'saveStyle':savedStyle={...style};persist('sf-style',savedStyle);updateSaved();toast(t('styleSaved'));break;case'restoreStyle':style={...savedStyle};renderTone();showStyle();break;case'removePhoto':removePortrait();break;case'removeStyle':savedStyle=null;persist('sf-style',null);showSaved();break;}});
document.querySelectorAll('.desktop-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.desktop-nav a').forEach(x=>x.classList.toggle('active',x===a))}));
render();

function applySeason(i){style={...style,season:i,color:0,...seasonalLooks[i]}}
function renderTone(){$('#toneOptions').innerHTML=toneButtons();$('#homeHanbok').innerHTML=hanbokSvg(garmentColors[style.bottom].hex,style.design);$('#paletteDots').innerHTML=['top','bottom','trim'].map(k=>`<span style="background:${garmentColors[style[k]].hex}"></span>`).join('');$('#colorName').textContent=seasons[style.season].en;$('#outfitCaption').textContent=(garmentColors[style.bottom][lang]||garmentColors[style.bottom].en)+' · '+t(style.design);}
function studioPalettes(){return ['top','bottom','trim'].map(part=>`<fieldset class="garment-palette"><legend>${t('part_'+part)} <span id="name_${part}"></span></legend><div class="garment-swatches">${garmentColors.map((c,i)=>`<button type="button" class="garment-swatch" data-garment="${part}" data-shade="${i}" style="--swatch:${c.hex}" title="${c[lang]||c.en}" aria-label="${t('part_'+part)} · ${c[lang]||c.en}"></button>`).join('')}</div></fieldset>`).join('')}
function showStyle(){showModal(`<div class="modal-inner studio-inner"><div class="eyebrow">PILK · HANBOK ATELIER</div><h2>${t('styleTitle')}</h2><p>${t('studioDesc')}</p><div class="style-layout"><div class="studio-preview-column"><div class="scene-preview"><img id="studioBackground" src="assets/scene.jpg" alt=""><div class="avatar" id="styleAvatar"></div><span class="scene-label" id="studioSceneLabel"></span><span class="preview-watermark">PILK ATELIER</span></div><div class="scene-options">${studioScenes.map(s=>`<button data-scene="${s.id}" aria-label="${s[lang]||s.en}"><img src="assets/${s.image}" alt=""><span>${s[lang]||s.en}</span></button>`).join('')}</div><div class="light-options" aria-label="${t('lightMood')}">${studioLights.map(l=>`<button data-light="${l.id}">${l[lang]||l.en}</button>`).join('')}</div><p class="small-note">${t('lightNote')}</p><div class="portrait-upload"><input type="file" id="portraitFile" accept="image/jpeg,image/png,image/webp,image/avif" class="file-input"><label class="button outline upload-label" for="portraitFile">${icon('camera')}<span id="portraitUploadLabel">${t(portraitImage?'photoChange':'photoUpload')}</span></label><p class="small-note">${t('photoPrivacy')}</p><p id="photoError" class="upload-error" role="status"></p></div><div id="photoTools" class="photo-tools ${portraitImage?'':'hidden'}"><div class="crop-intro"><canvas id="faceCropPreview" width="160" height="160" aria-label="${t('photoCropPreview')}"></canvas><div><b>${t('photoAlign')}</b><p>${t('photoAlignDesc')}</p></div><button class="round-button" data-action="removePhoto" aria-label="${t('photoRemove')}">${icon('trash')}</button></div><label for="faceZoom">${t('photoZoom')}<output id="zoomReadout">${cropState.zoom.toFixed(1)}×</output></label><input id="faceZoom" type="range" min="1" max="5" step=".05" value="${cropState.zoom}"><div class="crop-axis"><div><label for="faceX">${t('photoHorizontal')}</label><input id="faceX" type="range" min="0" max="100" value="${cropState.x}"></div><div><label for="faceY">${t('photoVertical')}</label><input id="faceY" type="range" min="0" max="100" value="${cropState.y}"></div></div></div><p class="small-note">${t('previewNote')}</p></div><div class="style-controls"><div class="studio-section-label"><span>01</span>${t('presetLabel')}</div><div class="tone-options" id="modalTones"></div><button class="studio-quiz" data-studio-quiz>${t('colorHelp')} ↗</button><div class="studio-section-label"><span>02</span>${t('designLabel')}</div><label class="sr-only" for="designSelect">${t('designLabel')}</label><select id="designSelect">${studioDesigns.map(k=>`<option value="${k}">${t(k)}</option>`).join('')}</select><div class="studio-section-label"><span>03</span>${t('paletteLabel')}<small>17 COLORS</small></div>${studioPalettes()}<div class="studio-section-label"><span>04</span>${t('detailLabel')}</div><label class="gold-control" for="goldToggle"><span>✦ ${t('goldLabel')}</span><input type="checkbox" id="goldToggle"></label><div class="hair-options">${studioHair.map(k=>`<button data-hair="${k}">${t('hair_'+k)}</button>`).join('')}</div><div class="rental-card"><div class="rental-card-top"><span>RENTAL NOTE</span>${icon('spark')}</div><h3>${t('rentalTitle')}</h3><p class="rental-phrase">이 색 조합으로 입고 싶어요.<small>この色の組み合わせで着たいです。</small></p><div id="rentalDetails"></div><p class="small-note">${t('rentalNote')}</p><button class="text-button" data-studio-copy>${t('copyLook')} ${icon('check')}</button></div><div class="studio-actions"><button class="button primary" data-action="saveStyle">${icon('bookmark')}${t('saveStyle')}</button><button class="button outline" id="exportStyle">${icon('camera')}${t('exportLook')}</button></div><p id="exportStatus" class="small-note" role="status"></p></div></div></div>`,'style');updateStyle();$('#designSelect').onchange=e=>{style.design=e.target.value;updateStyle();renderTone()};$('#goldToggle').onchange=e=>{style.gold=e.target.checked;updateStyle();renderTone()};$('#portraitFile').onchange=loadPortrait;$('#exportStyle').onclick=exportStudio;for(const [selector,key] of [['#faceZoom','zoom'],['#faceX','x'],['#faceY','y']])$(selector).oninput=e=>{cropState[key]=+e.target.value;updateFaceCrop();updateStyle();$('#zoomReadout').textContent=cropState.zoom.toFixed(1)+'×'};if(portraitImage)updateFaceCrop();}
function rentalText(){return `PILK · HANBOK ATELIER\n이 색 조합으로 입고 싶어요.\nこの色の組み合わせで着たいです。\n${copy.ko[style.design]} / ${copy.ja[style.design]}\n`+['top','bottom','trim'].map(k=>`${copy.ko['part_'+k]} / ${copy.ja['part_'+k]}: ${garmentColors[style[k]].ko} / ${garmentColors[style[k]].ja}`).join('\n')+`\n금박 / 金箔: ${style.gold?'ON':'OFF'}\n${copy.ko['hair_'+style.hair]} / ${copy.ja['hair_'+style.hair]}`}
function updateStyle(){if(!$('#styleAvatar'))return;$('#styleAvatar').innerHTML=hanbokSvg(garmentColors[style.bottom].hex,style.design,true);$('#modalTones').innerHTML=toneButtons();$('#designSelect').value=style.design;$('#goldToggle').checked=style.gold;const scene=studioScenes.find(s=>s.id===style.scene),light=studioLights.find(s=>s.id===style.light);$('#studioBackground').src='assets/'+scene.image;$('#studioBackground').alt=scene[lang]||scene.en;$('#studioBackground').style.filter=light.filter;$('#studioSceneLabel').textContent=(scene[lang]||scene.en)+' · '+t('illustration');for(const part of ['top','bottom','trim']){$('#name_'+part).textContent=garmentColors[style[part]][lang]||garmentColors[style[part]].en;document.querySelectorAll(`[data-garment="${part}"]`).forEach(b=>{const active=+b.dataset.shade===style[part];b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)})}for(const key of ['hair','scene','light'])document.querySelectorAll('[data-'+key+']').forEach(b=>{const active=b.dataset[key]===style[key];b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});$('#rentalDetails').innerHTML=`<div class="rental-design">${t(style.design)} · ${t('hair_'+style.hair)}${style.gold?' · '+t('goldLabel'):''}</div>`+['top','bottom','trim'].map(k=>`<div class="rental-row"><span>${t('part_'+k)}</span><b><i style="background:${garmentColors[style[k]].hex}"></i>${garmentColors[style[k]].ko} <small>${garmentColors[style[k]].ja}</small></b></div>`).join('')}
async function exportStudio(){const button=$('#exportStyle');button.disabled=true;const look={...style},imageData=hanbokSvg(garmentColors[look.bottom].hex,look.design,true,look);const load=src=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=src});try{const [bg,figure]=await Promise.all([load('assets/'+studioScenes.find(s=>s.id===look.scene).image),load('data:image/svg+xml;base64,'+btoa(imageData))]);const c=document.createElement('canvas');c.width=900;c.height=1200;const x=c.getContext('2d');const scale=Math.max(900/bg.width,1100/bg.height);x.filter=studioLights.find(s=>s.id===look.light).filter;x.drawImage(bg,(900-bg.width*scale)/2,(1100-bg.height*scale)/2,bg.width*scale,bg.height*scale);x.filter='none';x.drawImage(figure,120,230,660,840);x.fillStyle='#fbf9f5';x.fillRect(0,1100,900,100);x.fillStyle='#444c3d';x.font='24px sans-serif';x.fillText('PILK · HANBOK ATELIER',35,1140);x.font='16px sans-serif';x.fillText((studioScenes.find(s=>s.id===look.scene)[lang]||studioScenes.find(s=>s.id===look.scene).en)+' · '+t('illustration'),35,1175);const a=document.createElement('a');a.download='pilk-hanbok.png';a.href=c.toDataURL('image/png');a.click();if($('#exportStatus'))$('#exportStatus').textContent=t('photoDone')}catch{if($('#exportStatus'))$('#exportStatus').textContent=t('exportError')}finally{button.disabled=false}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.garment){style[b.dataset.garment]=+b.dataset.shade;updateStyle();renderTone()}for(const key of ['hair','scene','light'])if(b.dataset[key]){style[key]=b.dataset[key];updateStyle();renderTone()}if(b.hasAttribute('data-studio-quiz'))showQuiz();if(b.hasAttribute('data-studio-copy')){try{await navigator.clipboard.writeText(rentalText());toast(t('copyDone'))}catch{toast(t('copyError'))}}});
